#' Randomization Inference
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param block .
#' @param cluster .
#' @param stat .
#' @param tau .
#' @param sims .
#' @param exactMax .
#' @param seed .
#' @param ci .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$res$asDF}
#'
#' \code{as.data.frame(results$res)}
#'
#' @export
exri <- function(
    data,
    outcome,
    treat,
    control = "",
    block,
    cluster,
    stat = "diff",
    tau = 0,
    sims = 5000,
    exactMax = 20000,
    seed = 1234,
    ci = TRUE,
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exri requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(block), block, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- exriOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        block = block,
        cluster = cluster,
        stat = stat,
        tau = tau,
        sims = sims,
        exactMax = exactMax,
        seed = seed,
        ci = ci,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exriClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

